mapper.select:
select *
from Tblmi_usr


        and usr_sales_org_id = #{organizationId}


        and usr_sales_id = #{userId}

SELECT *
FROM tblmi_set_lst

    DEL_DT = 'N'

        and list_tp_id = #{list_tp_id}


        and list_dt_id = #{list_dt_id}


        and usr_grp_cd = #{usr_grp_cd}


ORDER BY FIELD(DEF_YN, 'Y') DESC, REG_DT DESC

select *
from Tblmi_cont_mst


        and seq = #{seq}


        and ch_tp = #{ch_tp}


        and inten_id = #{inten_id}


        and orig_id = #{orig_id}


        and inta_key = #{inta_key}


        and inta_ve = #{inta_ve}


Limit 1

select a.seq , a.CONT_TP , a.CONT_SUB , a.CONT_TOP_BODY , a.CONT_BODY , a.SEND_TP , b.list_val as send_to , b.list_nm AS send_nm , a.THM_URL , a.BR_YN , a.SUP_YN , a.MSG_TP , a.KKO_IMG_CD , a.KKO_IMG_URL , a.KKO_BTN_NM , a.KKO_BTN_URL , a.IMG_CD_1 , a.IMG_CD_2 , a.IMG_CD_3 , a.IMG_CD_4 , a.IMG_CD_5 , a.IMG_CD_6 , a.RCS_BTN_INS_TP , a.RCS_BTN_CNT , a.RCS_BTN_OBJ , a.RCS_BTN_1 , a.RCS_BTN_TP_1 , a.RCS_BTN_CONT_1 , a.RCS_BTN_2 , a.RCS_BTN_TP_2 , a.RCS_BTN_CONT_2 , a.RCS_BTN_3 , a.RCS_BTN_TP_3 , a.RCS_BTN_CONT_3 , a.RCS_FOOTER , a.KEY_ID , a.CONT_GRP_CD , #{reg_id} as reg_id from Tblmi_cont_lst as a INNER JOIN tblmi_set_lst AS b ON a.SEND_TO = b.SEQ
and a.SEQ = #{seq}
and a.CONT_CD = #{cont_cd}
and a.CONT_TP = #{cont_tp}
and a.CONT_GRP_CD = #{cont_grp_cd}
and a.USE_YN = #{use_yn}

mapper.insert:

    SELECT seq
    FROM tblmicp_cont_mst
    WHERE avo_id = #{avo_id}
        and inten_id = #{inten_id}
        and  orig_id = #{orig_id}
        and  inta_key = #{inta_key}

insert into tblmicp_cont_mst (
   cont_seq
   , ch_tp
   , cont_nm
   , sales_nm
   , avo_id
   , inten_id
   , orig_id
   , inta_key
   , inta_ve
   , pub_yn
   , cont_grp_cd
   , reg_id
   , upd_id
)
values (
   #{cont_seq}
   , #{ch_tp}
   , #{cont_nm}
   , #{sales_nm}
   , #{avo_id}
   , #{inten_id}
   , #{orig_id}
   , #{inta_key}
   , #{inta_ve}
   , #{pub_yn}
   , #{cont_grp_cd}
   , #{reg_id}
   , #{upd_id}
)
ON DUPLICATE KEY UPDATE
    cont_seq = values(cont_seq)
    , cont_nm = values(cont_nm)
    , sales_nm = values(sales_nm)
    , inta_ve = values(inta_ve)
    , pub_yn = values(pub_yn)
    , upd_id = values(upd_id)
